def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def pos(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return default

    def step_toward(a, b):
        ax, ay = a
        bx, by = b
        return [clamp_step(bx - ax), clamp_step(by - ay)]

    def step_away(a, b):
        ax, ay = a
        bx, by = b
        return [clamp_step(ax - bx), clamp_step(ay - by)]

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def safe_list(v):
        return v if isinstance(v, list) else []

    env = observation.get("environment_name", "resource_collection")
    sx, sy = pos(observation.get("self_position"))
    ox, oy = pos(observation.get("opponent_position"), (sx, sy))
    me = (sx, sy)
    opp = (ox, oy)

    width = observation.get("grid_width", 0)
    height = observation.get("grid_height", 0)
    if not isinstance(width, int):
        width = 0
    if not isinstance(height, int):
        height = 0

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            move = step_toward(me, opp)
            if move == [0, 0]:
                move = [1, 0] if width and sx < width - 1 else ([0, 1] if height and sy < height - 1 else [0, 0])
            return move
        corners = [(0, 0), (0, max(0, height - 1)), (max(0, width - 1), 0), (max(0, width - 1), max(0, height - 1))]
        target = None
        best = None
        for c in corners:
            d = manhattan(c, opp)
            if best is None or d > best:
                best = d
                target = c
        if target is None:
            return [0, 0]
        move = step_toward(me, target)
        if move == [0, 0]:
            move = step_away(me, opp)
        return move

    if env == "territory_control":
        targets = safe_list(observation.get("unclaimed_cells")) or safe_list(observation.get("opponent_territory")) or safe_list(observation.get("neutral_cells"))
        if targets:
            best = None
            target = None
            for item in targets:
                t = pos(item, None)
                if t is None:
                    continue
                d = manhattan(me, t)
                if best is None or d < best:
                    best = d
                    target = t
            if target is not None:
                move = step_toward(me, target)
                # small bias away from opponent if equally close
                if manhattan((sx + move[0], sy + move[1]), opp) < manhattan(me, opp):
                    alt = step_away(me, opp)
                    if alt != [0, 0]:
                        move = alt
                return move
        return step_away(me, opp) if opp != me else [0, 0]

    resources = safe_list(observation.get("resources")) or safe_list(observation.get("resource_positions")) or safe_list(observation.get("food"))
    if resources:
        best = None
        target = None
        for item in resources:
            t = pos(item, None)
            if t is None:
                continue
            d = manhattan(me, t)
            if best is None or d < best:
                best = d
                target = t
        if target is not None:
            move = step_toward(me, target)
            # denial/competition: if opponent is closer, bias to block by moving toward same target
            if manhattan(opp, target) < manhattan(me, target):
                return move
            return move

    # fallback: move toward center, otherwise pressure opponent
    cx = width // 2 if width else sx
    cy = height // 2 if height else sy
    center = (cx, cy)
    move = step_toward(me, center)
    if move == [0, 0]:
        move = step_toward(me, opp) if opp != me else [0, 0]
    return move

